function f(t){return!Number.isFinite(t)||t<0?"0 B":t<1024?`${t} B`:t<1024*1024?`${(t/1024).toFixed(1)} KB`:`${(t/1024/1024).toFixed(1)} MB`}function o(t){if(!t)return"";const r=new Date(t);if(Number.isNaN(r.getTime()))return t;const e=n=>String(n).padStart(2,"0");return`${r.getFullYear()}-${e(r.getMonth()+1)}-${e(r.getDate())} ${e(r.getHours())}:${e(r.getMinutes())}`}function i(t){if(!t)return"";const r=new Date(t);if(Number.isNaN(r.getTime()))return t;const e=n=>String(n).padStart(2,"0");return`${r.getFullYear()}-${e(r.getMonth()+1)}-${e(r.getDate())}`}function c(t){if(!t)return"";const r=new Date(t);if(Number.isNaN(r.getTime()))return t;const e=Date.now()-r.getTime(),n=60*1e3,a=60*n,u=24*a;return e<n?"刚刚":e<a?`${Math.floor(e/n)} 分钟前`:e<u?`${Math.floor(e/a)} 小时前`:e<30*u?`${Math.floor(e/u)} 天前`:i(t)}function m(t){return`${Math.round(t*100)}%`}export{f as a,i as b,m as c,o as d,c as f};
